package org.threeten.extra.chrono;

import static java.time.temporal.ChronoUnit.DAYS;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.LocalDate;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

@SuppressWarnings({ "static-method" })
public class TestSymmetry010Chronology_test_until_DAYS {

    public static Object[][] data_samples() {
        return new Object[][] {
                // Constantine the Great, Roman emperor (d. 337)
                sample(Symmetry010Date.of(1, 1, 1), LocalDate.of(1, 1, 1)),

                sample(Symmetry010Date.of(272, 2, 28), LocalDate.of(272, 2, 27)),
                sample(Symmetry010Date.of(272, 2, 27), LocalDate.of(272, 2, 26)),

                // Charlemagne, Frankish king (d. 814)
                sample(Symmetry010Date.of(742, 3, 27), LocalDate.of(742, 4, 2)),
                sample(Symmetry010Date.of(742, 4, 2), LocalDate.of(742, 4, 7)),

                // Norman Conquest: Battle of Hastings
                sample(Symmetry010Date.of(1066, 10, 14), LocalDate.of(1066, 10, 14)),

                // Francesco Petrarca - Petrarch, Italian scholar and poet in Renaissance Italy,
                // "Father of Humanism" (d. 1374)
                sample(Symmetry010Date.of(1304, 7, 21), LocalDate.of(1304, 7, 20)),
                sample(Symmetry010Date.of(1304, 7, 20), LocalDate.of(1304, 7, 19)),

                // Charles the Bold, French son of Isabella of Portugal, Duchess of Burgundy (d. 1477)
                sample(Symmetry010Date.of(1433, 11, 12), LocalDate.of(1433, 11, 10)),
                sample(Symmetry010Date.of(1433, 11, 10), LocalDate.of(1433, 11, 8)),

                // Leonardo da Vinci, Italian painter, sculptor, and architect (d. 1519)
                sample(Symmetry010Date.of(1452, 4, 11), LocalDate.of(1452, 4, 15)),
                sample(Symmetry010Date.of(1452, 4, 15), LocalDate.of(1452, 4, 19)),

                // Christopher Columbus's expedition makes landfall in the Caribbean.
                sample(Symmetry010Date.of(1492, 10, 10), LocalDate.of(1492, 10, 12)),
                sample(Symmetry010Date.of(1492, 10, 12), LocalDate.of(1492, 10, 14)),

                // Galileo Galilei, Italian astronomer and physicist (d. 1642)
                sample(Symmetry010Date.of(1564, 2, 18), LocalDate.of(1564, 2, 15)),
                sample(Symmetry010Date.of(1564, 2, 15), LocalDate.of(1564, 2, 12)),

                // William Shakespeare is baptized in Stratford-upon-Avon, Warwickshire, England
                // (date of actual birth is unknown, d. 1616).
                sample(Symmetry010Date.of(1564, 4, 28), LocalDate.of(1564, 4, 26)),
                sample(Symmetry010Date.of(1564, 4, 26), LocalDate.of(1564, 4, 24)),

                // Sir Isaac Newton, English physicist and mathematician (d. 1727)
                sample(Symmetry010Date.of(1643, 1, 7), LocalDate.of(1643, 1, 4)),
                sample(Symmetry010Date.of(1643, 1, 4), LocalDate.of(1643, 1, 1)),

                // Leonhard Euler, Swiss mathematician and physicist (d. 1783)
                sample(Symmetry010Date.of(1707, 4, 12), LocalDate.of(1707, 4, 15)),
                sample(Symmetry010Date.of(1707, 4, 15), LocalDate.of(1707, 4, 18)),

                // French Revolution: Citizens of Paris storm the Bastille.
                sample(Symmetry010Date.of(1789, 7, 16), LocalDate.of(1789, 7, 14)),
                sample(Symmetry010Date.of(1789, 7, 14), LocalDate.of(1789, 7, 12)),

                // Albert Einstein, German theoretical physicist (d. 1955)
                sample(Symmetry010Date.of(1879, 3, 14), LocalDate.of(1879, 3, 14)),

                // Dennis MacAlistair Ritchie, American computer scientist (d. 2011)
                sample(Symmetry010Date.of(1941, 9, 11), LocalDate.of(1941, 9, 9)),
                sample(Symmetry010Date.of(1941, 9, 9), LocalDate.of(1941, 9, 7)),

                // Unix time begins at 00:00:00 UTC/GMT.
                sample(Symmetry010Date.of(1970, 1, 4), LocalDate.of(1970, 1, 1)),
                sample(Symmetry010Date.of(1970, 1, 1), LocalDate.of(1969, 12, 29)),

                // Start of the 21st century / 3rd millennium
                sample(Symmetry010Date.of(1999, 12, 29), LocalDate.of(2000, 1, 1)),
                sample(Symmetry010Date.of(2000, 1, 1), LocalDate.of(2000, 1, 3)),
        };
    }

    private static Object[] sample(Symmetry010Date sym010, LocalDate iso) {
        return new Object[] { sym010, iso };
    }

    @ParameterizedTest
    @MethodSource("data_samples")
    public void test_until_DAYS(Symmetry010Date sym010, LocalDate iso) {
        assertEquals(0, sym010.until(iso.plusDays(0), DAYS));
        assertEquals(1, sym010.until(iso.plusDays(1), DAYS));
        assertEquals(35, sym010.until(iso.plusDays(35), DAYS));
        assertEquals(-40, sym010.until(iso.minusDays(40), DAYS));
    }
}
